/* ============================================================================
   OG-FONT — serif glyphs for the share-card images.

   Generated once from Georgia Bold: capitals, lowercase, digits and the
   punctuation a name/date needs. Sample 2's approved initials card uses
   only the capitals; Sample 1's names card renders full text. Data, not
   code — zero font dependencies on the edge. ~127 KB of a 1 MB budget.
   ========================================================================= */
"use strict";
const zlib = require("zlib");
const RAW = "";
const GLYPHS = JSON.parse(zlib.inflateSync(Buffer.from(RAW, "base64")).toString("utf8"));
module.exports = GLYPHS;
